def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append((oid, o))

    if not alive_opponents:
        return min(float(my_status['budget']), DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Competitive band estimation
    # If Alex/Bob were dominant yesterday, their bids likely anchor today's competition.
    target = None
    if yesterday_bids:
        # Use a robust statistic: median of yesterday bids
        sorted_b = sorted(yesterday_bids)
        mid = len(sorted_b) // 2
        if len(sorted_b) % 2 == 1:
            target = sorted_b[mid]
        else:
            target = 0.5 * (sorted_b[mid - 1] + sorted_b[mid])
        # Slightly above median to beat typical competitors
        target = target + 6.0
    else:
        target = 110.0

    # Adjust based on my HP and budget pressure
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # If I'm close to death, spend aggressively; if healthy, keep controlled aggression.
    if hp <= 2.0 or no_water_days >= 2:
        multiplier = 1.15
    elif hp <= 3.5:
        multiplier = 1.05
    else:
        multiplier = 0.98

    # Supply scaling: when supply is higher, competition may be less intense; reduce bid slightly.
    # Normalize supply between MIN_SUPPLY and MAX_SUPPLY.
    if MAX_SUPPLY > MIN_SUPPLY:
        s_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        s_norm = 0.5
    s_norm = 0.0 if s_norm < 0.0 else (1.0 if s_norm > 1.0 else s_norm)

    # Higher supply => bid less; lower supply => bid more.
    supply_adjust = 1.06 - 0.12 * s_norm

    bid = target * multiplier * supply_adjust

    # Hard caps to avoid bankrupting
    # Keep bid within a reasonable fraction of budget and daily salary.
    max_reasonable = min(budget, DAILY_SALARY * 0.95)
    min_reasonable = min(budget, DAILY_SALARY * 0.25)

    if bid > max_reasonable:
        bid = max_reasonable
    if bid < min_reasonable:
        bid = min_reasonable

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid
